//! Semantic conformance with the Lean specification (README §10.2, §10.5).
//!
//! `testdata/golden/vectors.json` is generated by `scripts/gen-golden.sh` from
//! `lean/PatternMatch/Golden.lean`. Every numeric leaf is an exact rational
//! string `"numerator/denominator"`; comparisons convert to `f64` and use a
//! relative tolerance because the Rust implementation is floating point.
//!
//! Each vector names its theorem ID (G1–G8), so a failure identifies the
//! spec-to-implementation link that broke.

use std::collections::BTreeSet;
use std::fs;
use std::path::PathBuf;

use nalgebra::{Matrix3, Vector2, Vector3};
use pm_core::geometry::{
    Homography, Similarity, affine_normalize, cross_ratio, det_points, mobius, normalized_dlt,
    similarity_from_block,
};
use pm_core::refine::{required_iterations_exact, required_iterations_from_q};

/// Relative tolerance for converting exact rational golden values to `f64`.
const TOL: f64 = 1e-9;

#[derive(Debug, serde::Deserialize)]
struct GoldenFile {
    format: String,
    version: u32,
    vectors: Vec<GoldenVector>,
}

#[derive(Debug, serde::Deserialize)]
struct SimilarityJson {
    scale: String,
    theta_deg: String,
    tx: String,
    ty: String,
}

#[derive(Debug, serde::Deserialize)]
struct CorrespondenceJson {
    x: String,
    y: String,
    u: String,
    v: String,
}

impl CorrespondenceJson {
    fn source(&self) -> Vector2<f64> {
        Vector2::new(q(&self.x), q(&self.y))
    }

    fn target(&self) -> Vector2<f64> {
        Vector2::new(q(&self.u), q(&self.v))
    }
}

#[derive(Debug, serde::Deserialize)]
#[serde(tag = "kind")]
enum GoldenVector {
    #[serde(rename = "homography_action")]
    HomographyAction {
        id: String,
        theorem: String,
        h1: Vec<String>,
        h2: Vec<String>,
        p: Vec<String>,
        expected: Vec<String>,
    },
    #[serde(rename = "homography_scaling")]
    HomographyScaling {
        id: String,
        theorem: String,
        h: Vec<String>,
        c: String,
        p: Vec<String>,
        expected: Vec<String>,
    },
    #[serde(rename = "homography_inverse")]
    HomographyInverse {
        id: String,
        theorem: String,
        h: Vec<String>,
        h_inv: Vec<String>,
        p: Vec<String>,
        expected: Vec<String>,
    },
    #[serde(rename = "similarity_compose")]
    SimilarityCompose {
        id: String,
        theorem: String,
        first: SimilarityJson,
        second: SimilarityJson,
        expected: SimilarityJson,
        expected_matrix: Vec<String>,
    },
    #[serde(rename = "similarity_decomposition")]
    SimilarityDecomposition {
        id: String,
        theorem: String,
        a: String,
        b: String,
        expected_scale: String,
        expected_cos: String,
        expected_sin: String,
    },
    #[serde(rename = "cross_ratio")]
    CrossRatio {
        id: String,
        theorem: String,
        x: Vec<String>,
        mobius: Vec<String>,
        expected: String,
        expected_transformed: String,
    },
    #[serde(rename = "collinearity")]
    Collinearity {
        id: String,
        theorem: String,
        h: Vec<String>,
        points: Vec<Vec<String>>,
        expected_det: String,
    },
    #[serde(rename = "jacobian")]
    Jacobian {
        id: String,
        theorem: String,
        h: Vec<String>,
        expected_origin: Vec<String>,
        expected_jacobian: Vec<String>,
        #[serde(default)]
        expected_angle_deg: Option<String>,
        #[serde(default)]
        expected_scale: Option<String>,
    },
    #[serde(rename = "dlt_solution")]
    DltSolution {
        id: String,
        theorem: String,
        correspondences: Vec<CorrespondenceJson>,
        expected: Vec<String>,
        expected_det_nonzero: bool,
    },
    #[serde(rename = "dlt_degenerate")]
    DltDegenerate {
        id: String,
        theorem: String,
        correspondences: Vec<CorrespondenceJson>,
        expected_rejected: bool,
    },
    #[serde(rename = "ransac_probability")]
    RansacProbability {
        id: String,
        theorem: String,
        n: usize,
        #[serde(rename = "I")]
        inliers: usize,
        k: usize,
        expected_favorable: usize,
        expected_total: usize,
        expected_q: String,
        expected_bound: String,
    },
    #[serde(rename = "ransac_bound")]
    RansacBound {
        id: String,
        theorem: String,
        n: usize,
        #[serde(rename = "I")]
        inliers: usize,
        k: usize,
        expected_q: String,
        expected_bound: String,
    },
    #[serde(rename = "ransac_success")]
    RansacSuccess {
        id: String,
        theorem: String,
        q: String,
        #[serde(rename = "N")]
        iterations: usize,
        expected: String,
    },
    #[serde(rename = "ransac_monotonicity")]
    RansacMonotonicity {
        id: String,
        theorem: String,
        q: String,
        #[serde(rename = "N_low")]
        n_low: usize,
        #[serde(rename = "N_high")]
        n_high: usize,
        n: usize,
        #[serde(rename = "I_low")]
        inliers_low: usize,
        #[serde(rename = "I_high")]
        inliers_high: usize,
        #[serde(rename = "k_low")]
        k_low: usize,
        #[serde(rename = "k_high")]
        k_high: usize,
        expected_monotone: bool,
    },
    #[serde(rename = "ransac_iterations")]
    RansacIterations {
        id: String,
        theorem: String,
        #[serde(rename = "P")]
        confidence: String,
        q: String,
        cap: usize,
        expected: usize,
    },
}

impl GoldenVector {
    fn id(&self) -> &str {
        match self {
            Self::HomographyAction { id, .. }
            | Self::HomographyScaling { id, .. }
            | Self::HomographyInverse { id, .. }
            | Self::SimilarityCompose { id, .. }
            | Self::SimilarityDecomposition { id, .. }
            | Self::CrossRatio { id, .. }
            | Self::Collinearity { id, .. }
            | Self::Jacobian { id, .. }
            | Self::DltSolution { id, .. }
            | Self::DltDegenerate { id, .. }
            | Self::RansacProbability { id, .. }
            | Self::RansacBound { id, .. }
            | Self::RansacSuccess { id, .. }
            | Self::RansacMonotonicity { id, .. }
            | Self::RansacIterations { id, .. } => id,
        }
    }

    fn theorem(&self) -> &str {
        match self {
            Self::HomographyAction { theorem, .. }
            | Self::HomographyScaling { theorem, .. }
            | Self::HomographyInverse { theorem, .. }
            | Self::SimilarityCompose { theorem, .. }
            | Self::SimilarityDecomposition { theorem, .. }
            | Self::CrossRatio { theorem, .. }
            | Self::Collinearity { theorem, .. }
            | Self::Jacobian { theorem, .. }
            | Self::DltSolution { theorem, .. }
            | Self::DltDegenerate { theorem, .. }
            | Self::RansacProbability { theorem, .. }
            | Self::RansacBound { theorem, .. }
            | Self::RansacSuccess { theorem, .. }
            | Self::RansacMonotonicity { theorem, .. }
            | Self::RansacIterations { theorem, .. } => theorem,
        }
    }
}

/// Parse an exact rational string (`"3/5"`) or decimal into `f64`.
fn q(text: &str) -> f64 {
    match text.split_once('/') {
        Some((num, den)) => {
            let num: f64 = num
                .parse()
                .unwrap_or_else(|_| panic!("bad numerator {text:?}"));
            let den: f64 = den
                .parse()
                .unwrap_or_else(|_| panic!("bad denominator {text:?}"));
            num / den
        }
        None => text
            .parse()
            .unwrap_or_else(|_| panic!("bad number {text:?}")),
    }
}

fn mat3(values: &[String], context: &str) -> Matrix3<f64> {
    assert_eq!(values.len(), 9, "{context}: expected 9 matrix entries");
    Matrix3::from_row_slice(&values.iter().map(|v| q(v)).collect::<Vec<_>>())
}

fn vec3(values: &[String], context: &str) -> Vector3<f64> {
    assert_eq!(values.len(), 3, "{context}: expected a 3-vector");
    Vector3::new(q(&values[0]), q(&values[1]), q(&values[2]))
}

fn vec2(values: &[String], context: &str) -> Vector2<f64> {
    assert!(
        values.len() >= 2,
        "{context}: expected at least two coordinates"
    );
    Vector2::new(q(&values[0]), q(&values[1]))
}

fn assert_close(actual: f64, expected: f64, vector: &str, theorem: &str, what: &str) {
    let scale = expected.abs().max(1.0);
    assert!(
        (actual - expected).abs() <= TOL * scale,
        "{vector} [{theorem}] {what}: actual {actual}, expected {expected}"
    );
}

fn assert_matrix_close(
    actual: &Matrix3<f64>,
    expected: &Matrix3<f64>,
    vector: &str,
    theorem: &str,
    what: &str,
) {
    for i in 0..3 {
        for j in 0..3 {
            assert_close(
                actual[(i, j)],
                expected[(i, j)],
                vector,
                theorem,
                &format!("{what}[{i},{j}]"),
            );
        }
    }
}

fn similarity_from_json(value: &SimilarityJson) -> Similarity {
    Similarity {
        scale: q(&value.scale),
        theta: q(&value.theta_deg).to_radians(),
        tx: q(&value.tx),
        ty: q(&value.ty),
    }
}

fn check_vector(vector: &GoldenVector) {
    let id = vector.id();
    let theorem = vector.theorem();
    match vector {
        GoldenVector::HomographyAction {
            h1,
            h2,
            p,
            expected,
            ..
        } => {
            let h1 = Homography::from_matrix(mat3(h1, id));
            let h2 = Homography::from_matrix(mat3(h2, id));
            let p = vec3(p, id);
            let expected = vec3(expected, id);
            let composed = h1.compose(&h2).act_homogeneous(p);
            let sequential = h1.act_homogeneous(h2.act_homogeneous(p));
            for i in 0..3 {
                assert_close(composed[i], expected[i], id, theorem, "composed action");
                assert_close(sequential[i], expected[i], id, theorem, "sequential action");
            }
        }
        GoldenVector::HomographyScaling {
            h, c, p, expected, ..
        } => {
            let h = Homography::from_matrix(mat3(h, id));
            let c = q(c);
            let homogeneous = vec3(p, id);
            let p = Vector2::new(homogeneous.x / homogeneous.z, homogeneous.y / homogeneous.z);
            let expected = vec2(expected, id);
            let scaled = Homography::from_matrix(h.matrix() * c);
            let actual = scaled
                .try_act_point(p)
                .expect("finite homogeneous coordinate");
            let plain = h.try_act_point(p).expect("finite homogeneous coordinate");
            assert_close(actual.x, expected.x, id, theorem, "scaled action x");
            assert_close(actual.y, expected.y, id, theorem, "scaled action y");
            assert_close(plain.x, expected.x, id, theorem, "plain action x");
            assert_close(plain.y, expected.y, id, theorem, "plain action y");
        }
        GoldenVector::HomographyInverse {
            h,
            h_inv,
            p,
            expected,
            ..
        } => {
            let h = Homography::from_matrix(mat3(h, id));
            let expected_inverse = mat3(h_inv, id);
            let inverse = h.try_inverse().expect("golden H is invertible");
            assert_matrix_close(
                inverse.matrix(),
                &expected_inverse,
                id,
                theorem,
                "inverse matrix",
            );
            let p = vec3(p, id);
            let roundtrip = inverse.act_homogeneous(h.act_homogeneous(p));
            let actual = affine_normalize(roundtrip).expect("affine roundtrip");
            let expected = vec2(expected, id);
            assert_close(actual.x, expected.x, id, theorem, "roundtrip x");
            assert_close(actual.y, expected.y, id, theorem, "roundtrip y");
        }
        GoldenVector::SimilarityCompose {
            first,
            second,
            expected,
            expected_matrix,
            ..
        } => {
            let first = similarity_from_json(first);
            let second = similarity_from_json(second);
            let expected = similarity_from_json(expected);
            let composed = first.compose(&second);
            assert_close(
                composed.scale,
                expected.scale,
                id,
                theorem,
                "composed scale",
            );
            // Angles are compared modulo a full turn.
            let two_pi = std::f64::consts::TAU;
            let delta = (composed.theta - expected.theta).rem_euclid(two_pi);
            let delta = delta.min(two_pi - delta);
            assert!(
                delta <= TOL,
                "{id} [{theorem}] composed theta: actual {}, expected {}",
                composed.theta,
                expected.theta
            );
            assert_close(composed.tx, expected.tx, id, theorem, "composed tx");
            assert_close(composed.ty, expected.ty, id, theorem, "composed ty");
            assert_matrix_close(
                composed.embed().matrix(),
                &mat3(expected_matrix, id),
                id,
                theorem,
                "embedded composition",
            );
        }
        GoldenVector::SimilarityDecomposition {
            a,
            b,
            expected_scale,
            expected_cos,
            expected_sin,
            ..
        } => {
            let (scale, theta) =
                similarity_from_block(q(a), q(b)).expect("golden block is non-zero");
            assert_close(scale, q(expected_scale), id, theorem, "scale");
            assert_close(theta.cos(), q(expected_cos), id, theorem, "cos");
            assert_close(theta.sin(), q(expected_sin), id, theorem, "sin");
        }
        GoldenVector::CrossRatio {
            x,
            mobius: transform,
            expected,
            expected_transformed,
            ..
        } => {
            assert_eq!(x.len(), 4, "{id}: cross-ratio needs four points");
            assert_eq!(transform.len(), 4, "{id}: Möbius needs a,b,c,d");
            let x = [q(&x[0]), q(&x[1]), q(&x[2]), q(&x[3])];
            let direct = cross_ratio(x[0], x[1], x[2], x[3]);
            assert_close(direct, q(expected), id, theorem, "direct cross-ratio");
            let a = q(&transform[0]);
            let b = q(&transform[1]);
            let c = q(&transform[2]);
            let d = q(&transform[3]);
            let transformed = x.map(|value| mobius(a, b, c, d, value));
            let image = cross_ratio(
                transformed[0],
                transformed[1],
                transformed[2],
                transformed[3],
            );
            assert_close(
                image,
                q(expected_transformed),
                id,
                theorem,
                "transformed cross-ratio",
            );
            assert_close(image, direct, id, theorem, "Möbius invariance");
        }
        GoldenVector::Collinearity {
            h,
            points,
            expected_det,
            ..
        } => {
            assert_eq!(points.len(), 3, "{id}: collinearity needs three points");
            let h = Homography::from_matrix(mat3(h, id));
            let p = vec3(&points[0], id);
            let qv = vec3(&points[1], id);
            let r = vec3(&points[2], id);
            let expected = q(expected_det);
            assert_close(
                det_points(p, qv, r),
                expected,
                id,
                theorem,
                "input determinant",
            );
            assert_close(
                det_points(
                    h.act_homogeneous(p),
                    h.act_homogeneous(qv),
                    h.act_homogeneous(r),
                ),
                expected,
                id,
                theorem,
                "transformed determinant",
            );
        }
        GoldenVector::Jacobian {
            h,
            expected_origin,
            expected_jacobian,
            expected_angle_deg,
            expected_scale,
            ..
        } => {
            let h = Homography::from_matrix(mat3(h, id));
            let origin = h.origin().expect("finite h33");
            let expected_origin = vec2(expected_origin, id);
            assert_close(origin.x, expected_origin.x, id, theorem, "origin x");
            assert_close(origin.y, expected_origin.y, id, theorem, "origin y");

            assert_eq!(expected_jacobian.len(), 4, "{id}: expected 2×2 Jacobian");
            let j = h.jacobian_at_origin().expect("finite h33");
            let entries = [j[(0, 0)], j[(0, 1)], j[(1, 0)], j[(1, 1)]];
            for (index, entry) in entries.iter().enumerate() {
                assert_close(
                    *entry,
                    q(&expected_jacobian[index]),
                    id,
                    theorem,
                    &format!("Jacobian entry {index}"),
                );
            }

            if let (Some(angle), Some(scale)) = (expected_angle_deg, expected_scale) {
                let pose = h.pose_at_origin().expect("non-singular Jacobian");
                assert_close(pose.angle.to_degrees(), q(angle), id, theorem, "pose angle");
                assert_close(pose.scale, q(scale), id, theorem, "pose scale");
            }
        }
        GoldenVector::DltSolution {
            correspondences,
            expected,
            expected_det_nonzero,
            ..
        } => {
            let points: Vec<_> = correspondences
                .iter()
                .map(|c| (c.source(), c.target()))
                .collect();
            let solution =
                normalized_dlt(&points).expect("golden correspondence set is not degenerate");
            let actual = solution.normalized_for_output();
            let expected = mat3(expected, id);
            for i in 0..3 {
                for j in 0..3 {
                    assert_close(
                        actual[(i, j)],
                        expected[(i, j)],
                        id,
                        theorem,
                        &format!("DLT solution[{i},{j}]"),
                    );
                }
            }
            if *expected_det_nonzero {
                assert!(
                    solution.determinant().abs() > 1e-9,
                    "{id} [{theorem}]: expected a non-singular solution"
                );
            }
        }
        GoldenVector::DltDegenerate {
            correspondences,
            expected_rejected,
            ..
        } => {
            let points: Vec<_> = correspondences
                .iter()
                .map(|c| (c.source(), c.target()))
                .collect();
            let solution = normalized_dlt(&points);
            if *expected_rejected {
                assert!(
                    solution.is_none(),
                    "{id} [{theorem}]: degenerate sample was accepted"
                );
            } else {
                assert!(
                    solution.is_some(),
                    "{id} [{theorem}]: valid sample was rejected"
                );
            }
        }
        GoldenVector::RansacProbability {
            n,
            inliers,
            k,
            expected_favorable,
            expected_total,
            expected_q,
            expected_bound,
            ..
        } => {
            let (favorable, total) = choose_ratio(*n, *inliers, *k);
            assert_eq!(
                favorable, *expected_favorable,
                "{id} [{theorem}]: favorable sample count"
            );
            assert_eq!(
                total, *expected_total,
                "{id} [{theorem}]: total sample count"
            );
            let probability = favorable as f64 / total as f64;
            assert_close(
                probability,
                q(expected_q),
                id,
                theorem,
                "all-inlier probability",
            );
            let bound = (*inliers as f64 / *n as f64).powi(*k as i32);
            assert_close(bound, q(expected_bound), id, theorem, "conservative bound");
            assert!(
                probability <= bound + 1e-12,
                "{id} [{theorem}]: probability {probability} exceeds bound {bound}"
            );
        }
        GoldenVector::RansacBound {
            n,
            inliers,
            k,
            expected_q,
            expected_bound,
            ..
        } => {
            let (favorable, total) = choose_ratio(*n, *inliers, *k);
            let probability = favorable as f64 / total as f64;
            assert_close(probability, q(expected_q), id, theorem, "probability");
            let bound = (*inliers as f64 / *n as f64).powi(*k as i32);
            assert_close(bound, q(expected_bound), id, theorem, "bound");
            assert!(
                probability <= bound + 1e-12,
                "{id} [{theorem}]: R2 bound violated: {probability} > {bound}"
            );
        }
        GoldenVector::RansacSuccess {
            q: success_q,
            iterations,
            expected,
            ..
        } => {
            let success_q = q(success_q);
            let actual = 1.0 - (1.0 - success_q).powi(*iterations as i32);
            assert_close(actual, q(expected), id, theorem, "success probability");
        }
        GoldenVector::RansacMonotonicity {
            q: success_q,
            n_low,
            n_high,
            n,
            inliers_low,
            inliers_high,
            k_low,
            k_high,
            expected_monotone,
            ..
        } => {
            let success_q = q(success_q);
            let success = |iterations: usize| 1.0 - (1.0 - success_q).powi(iterations as i32);
            let inlier_probability = |inliers: usize, k: usize| {
                let (favorable, total) = choose_ratio(*n, inliers, k);
                favorable as f64 / total as f64
            };
            let monotone_in_n = success(*n_low) <= success(*n_high) + 1e-12;
            let monotone_in_i = inlier_probability(*inliers_low, *k_low)
                <= inlier_probability(*inliers_high, *k_low) + 1e-12;
            let monotone_in_k = inlier_probability(*inliers_high, *k_high)
                <= inlier_probability(*inliers_high, *k_low) + 1e-12;
            if *expected_monotone {
                assert!(
                    monotone_in_n && monotone_in_i && monotone_in_k,
                    "{id} [{theorem}]: monotonicity failed: N {monotone_in_n}, \
                     I {monotone_in_i}, k {monotone_in_k}"
                );
            }
        }
        GoldenVector::RansacIterations {
            confidence,
            q: sample_q,
            cap,
            expected,
            ..
        } => {
            let confidence = q(confidence);
            let sample_q = q(sample_q);
            let exact = required_iterations_exact(confidence, sample_q, *cap);
            assert_eq!(exact, *expected, "{id} [{theorem}]: exact iteration count");
            let formula = required_iterations_from_q(confidence, sample_q, *cap);
            assert_eq!(
                formula, *expected,
                "{id} [{theorem}]: log-formula iteration count"
            );
            let success = 1.0 - (1.0 - sample_q).powi(*expected as i32);
            assert!(
                success + 1e-12 >= confidence,
                "{id} [{theorem}]: success {success} below confidence {confidence}"
            );
        }
    }
}

/// Exact binomial coefficient for small golden-vector arguments.
fn choose(n: usize, k: usize) -> usize {
    if k > n {
        return 0;
    }
    let k = k.min(n - k);
    (0..k).fold(1usize, |acc, i| acc * (n - i) / (i + 1))
}

/// Favorable and total counts for the all-inlier sample event (R1).
fn choose_ratio(n: usize, inliers: usize, k: usize) -> (usize, usize) {
    (choose(inliers, k), choose(n, k))
}

#[test]
fn committed_golden_vectors_conform_to_spec() {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("..")
        .join("..")
        .join("testdata/golden/vectors.json");
    let text =
        fs::read_to_string(&path).unwrap_or_else(|err| panic!("read {}: {err}", path.display()));
    let parsed: GoldenFile =
        serde_json::from_str(&text).unwrap_or_else(|err| panic!("parse {}: {err}", path.display()));

    assert_eq!(parsed.format, "pattern-match-golden");
    assert_eq!(parsed.version, 1);
    assert!(
        !parsed.vectors.is_empty(),
        "golden vectors are empty; run scripts/gen-golden.sh"
    );

    let mut ids = BTreeSet::new();
    let mut theorems = BTreeSet::new();
    for vector in &parsed.vectors {
        assert!(
            ids.insert(vector.id().to_owned()),
            "duplicate golden vector id: {}",
            vector.id()
        );
        theorems.insert(vector.theorem().to_owned());
        check_vector(vector);
    }

    for required in [
        "G1", "G2", "G3", "G4", "G5", "G6", "G7", "G8", "D3", "D4", "D5", "R1", "R2", "R3", "R4",
        "R5",
    ] {
        assert!(
            theorems.contains(required),
            "golden vectors do not cover theorem {required}"
        );
    }
}
